import { chromium } from 'playwright-core';

const browser = await chromium.launch({ headless: true, channel: 'chrome' });
const ctx = await browser.newContext({ viewport: { width: 375, height: 812 }, locale: 'de-DE', serviceWorkers: 'allow' });
ctx.setDefaultTimeout(4000);
const page = await ctx.newPage();
await page.goto('http://localhost:4173', { waitUntil: 'load' });
await page.waitForTimeout(800);

// create 2 habits (like the smoke test)
await page.getByTestId('habit-add').first().click();
await page.getByTestId('habit-name').first().fill('Wasser trinken');
await page.getByTestId('habit-save').first().click();
await page.waitForTimeout(300);
await page.getByTestId('habit-add').first().click();
await page.getByTestId('habit-name').first().fill('Lesen');
await page.getByTestId('habit-save').first().click();
await page.waitForTimeout(300);

// toggle habit 1 (done)
await page.getByTestId('nav-today').first().click();
await page.waitForTimeout(300);
await page.locator('li[data-testid="habit-item"]').nth(0).getByTestId('habit-toggle').click();
await page.waitForTimeout(300);
// set mood 2 today
await page.getByTestId('nav-settings').first().click();
await page.waitForTimeout(300);
await page.getByTestId('mood-2').first().click();
await page.waitForTimeout(300);

// go to week
await page.getByTestId('nav-week').first().click();
await page.waitForTimeout(900);

const info = await page.evaluate(() => {
  const c = document.querySelector('li[data-testid="week-chart"]');
  const shapes = c.querySelectorAll('svg path, svg rect, svg circle').length;
  const detail = {
    path: c.querySelectorAll('svg path').length,
    rect: c.querySelectorAll('svg rect').length,
    circle: c.querySelectorAll('svg circle').length,
    barRects: [...c.querySelectorAll('svg rect')].map(r => Math.round(r.getAttribute('height'))),
    linePaths: [...c.querySelectorAll('svg path')].map(p => p.getAttribute('d')?.slice(0, 80)),
    circles: [...c.querySelectorAll('svg circle')].map(r => ({ cx: r.getAttribute('cx'), cy: r.getAttribute('cy'), r: r.getAttribute('r') })),
    allSvgTags: [...c.querySelectorAll('svg > *')].map(e => e.tagName),
  };
  return { shapes, detail };
});
console.log(JSON.stringify(info, null, 2));

await browser.close();

